#include <cstdio>
#include <string>
#include <iostream>

int main() {
    std::string t, p;
    std::getline(std::cin, t);
    std::getline(std::cin, p);
    if (p.empty() || p.size() > t.size()) { printf("0\n"); return 0; }

    int cnt = 0;
    size_t i = 0;
    while (i + p.size() <= t.size()) {
        if (t.compare(i, p.size(), p) == 0) { ++cnt; i += p.size(); }
        else ++i;
    }
    printf("%d\n", cnt);
    return 0;
}
